import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { isModalInterceptEnabled } from "./feature-flags";

describe("isModalInterceptEnabled", () => {
  const original = process.env.MODAL_INTERCEPT_ENABLED;

  beforeEach(() => {
    delete process.env.MODAL_INTERCEPT_ENABLED;
  });

  afterEach(() => {
    if (original === undefined) {
      delete process.env.MODAL_INTERCEPT_ENABLED;
    } else {
      process.env.MODAL_INTERCEPT_ENABLED = original;
    }
  });

  it("returns false when env var is unset", () => {
    expect(isModalInterceptEnabled()).toBe(false);
  });

  it("returns false when env var is empty string", () => {
    process.env.MODAL_INTERCEPT_ENABLED = "";
    expect(isModalInterceptEnabled()).toBe(false);
  });

  it("returns true when env var is exactly 'true'", () => {
    process.env.MODAL_INTERCEPT_ENABLED = "true";
    expect(isModalInterceptEnabled()).toBe(true);
  });

  it("returns false for case-mismatched 'TRUE'", () => {
    process.env.MODAL_INTERCEPT_ENABLED = "TRUE";
    expect(isModalInterceptEnabled()).toBe(false);
  });

  it("returns false for '1'", () => {
    process.env.MODAL_INTERCEPT_ENABLED = "1";
    expect(isModalInterceptEnabled()).toBe(false);
  });

  it("returns false for 'false'", () => {
    process.env.MODAL_INTERCEPT_ENABLED = "false";
    expect(isModalInterceptEnabled()).toBe(false);
  });
});

import { describe, it, expect } from "vitest";
import { sorensenDice, fuzzyMatchCandidates } from "./fuzzy-match";

describe("sorensenDice", () => {
  it("returns 1.0 for exact match", () => {
    expect(sorensenDice("AG1 Pro", "AG1 Pro")).toBe(1);
  });

  it("is case-insensitive", () => {
    expect(sorensenDice("AG1 Pro", "ag1 pro")).toBe(1);
  });

  it("trims surrounding whitespace", () => {
    expect(sorensenDice("  AG1 Pro  ", "AG1 Pro")).toBe(1);
  });

  it("returns low score for unrelated strings", () => {
    // "Convergix" vs "Bonterra" share almost no bigrams
    const score = sorensenDice("Convergix", "Bonterra");
    expect(score).toBeLessThan(0.2);
  });

  it("returns 0 for completely disjoint short strings", () => {
    expect(sorensenDice("ab", "cd")).toBe(0);
  });

  it("returns intermediate score for partial overlap", () => {
    // "AG1 Pro" vs "AG1 Pro Subscriber 2026" — shared bigrams from "AG1 Pro "
    const score = sorensenDice("AG1 Pro", "AG1 Pro Subscriber 2026");
    expect(score).toBeGreaterThan(0.4);
    expect(score).toBeLessThan(1);
  });

  it("handles single-char inputs (length < 2 fallback)", () => {
    expect(sorensenDice("a", "a")).toBe(1);
    expect(sorensenDice("a", "b")).toBe(0);
    expect(sorensenDice("a", "ab")).toBe(0);
  });

  it("handles empty strings (length < 2 fallback)", () => {
    expect(sorensenDice("", "")).toBe(1);
    expect(sorensenDice("", "a")).toBe(0);
  });

  it("handles unicode characters", () => {
    expect(sorensenDice("café", "café")).toBe(1);
    expect(sorensenDice("café", "cafe")).toBeGreaterThan(0.3);
  });

  it("counts duplicate bigrams correctly", () => {
    // "aaaa" vs "aaa" — bigrams of "aaaa" = aa,aa,aa (3 of "aa"); "aaa" = aa,aa (2)
    // intersect = min(3,2) = 2; total = 3 + 2 = 5; score = 4/5 = 0.8
    expect(sorensenDice("aaaa", "aaa")).toBeCloseTo(0.8, 2);
  });
});

describe("fuzzyMatchCandidates", () => {
  type Project = { id: string; name: string };
  const projects: Project[] = [
    { id: "p1", name: "AG1 Pro" },
    { id: "p2", name: "AG1 Pro Subscriber 2026" },
    { id: "p3", name: "Convergix CDS Messaging" },
    { id: "p4", name: "Bonterra Brand Refresh" },
  ];

  it("returns single candidate matching above default threshold", () => {
    const matches = fuzzyMatchCandidates(
      "Convergix CDS",
      projects,
      (p) => p.name,
    );
    expect(matches.length).toBeGreaterThanOrEqual(1);
    expect(matches.some((m) => m.id === "p3")).toBe(true);
  });

  it("returns multiple candidates above threshold", () => {
    const matches = fuzzyMatchCandidates("AG1 Pro", projects, (p) => p.name, 0.5);
    expect(matches.length).toBe(2);
    expect(matches.map((m) => m.id).sort()).toEqual(["p1", "p2"]);
  });

  it("returns empty array when no candidate clears threshold", () => {
    const matches = fuzzyMatchCandidates(
      "ZZZ unrelated",
      projects,
      (p) => p.name,
    );
    expect(matches).toHaveLength(0);
  });

  it("respects custom higher threshold (0.9)", () => {
    // "AG1 Pro" alone clears 0.9 only against "AG1 Pro" exact match
    const matches = fuzzyMatchCandidates("AG1 Pro", projects, (p) => p.name, 0.9);
    expect(matches.map((m) => m.id)).toEqual(["p1"]);
  });

  it("respects custom lower threshold (0.2)", () => {
    const matches = fuzzyMatchCandidates(
      "Convergix",
      projects,
      (p) => p.name,
      0.2,
    );
    expect(matches.length).toBeGreaterThanOrEqual(1);
  });
});

/**
 * Lint guard: every `create_*` tool exported by bot-tools.ts must be either
 * in INTERCEPT_ALLOWLIST (modal-routed) or INTERCEPT_EXCLUDED (deliberate
 * opt-out). Without this guard a future `create_foo` tool ships and silently
 * bypasses the modal intercept layer.
 *
 * Reads the bot-tools.ts source as raw text and pulls every key matching
 * `^create_[a-z_]+\: tool\(` so we don't have to instantiate the tool factory
 * (which would pull in DB modules).
 */
import { describe, it, expect } from "vitest";
import { readFileSync } from "fs";
import { join } from "path";
import {
  INTERCEPT_ALLOWLIST,
  INTERCEPT_EXCLUDED,
} from "./operations-utils";

function extractCreateToolNames(): string[] {
  const path = join(
    process.cwd(),
    "src/lib/slack/bot-tools.ts",
  );
  const src = readFileSync(path, "utf8");
  // Match keys like `create_project: tool(`, `create_week_item: tool(`.
  // Captures the snake-case identifier between leading whitespace + `:` + `tool(`.
  const re = /(^|\s)(create_[a-z_]+)\s*:\s*tool\s*\(/gm;
  const names = new Set<string>();
  let m: RegExpExecArray | null;
  while ((m = re.exec(src)) !== null) {
    names.add(m[2]);
  }
  return [...names];
}

describe("intercept-allowlist lint guard", () => {
  it("can extract at least one create_* tool from bot-tools.ts (sanity)", () => {
    const names = extractCreateToolNames();
    expect(names.length).toBeGreaterThan(0);
  });

  it("every create_* tool is in INTERCEPT_ALLOWLIST or INTERCEPT_EXCLUDED", () => {
    const names = extractCreateToolNames();
    const allowed = new Set<string>([
      ...INTERCEPT_ALLOWLIST,
      ...INTERCEPT_EXCLUDED,
    ]);
    const uncovered = names.filter((n) => !allowed.has(n));
    expect(
      uncovered,
      `Found create_* tools not in INTERCEPT_ALLOWLIST or INTERCEPT_EXCLUDED: ${uncovered.join(", ")}. Add them to one of the constants in src/lib/runway/operations-utils.ts.`,
    ).toEqual([]);
  });

  it("INTERCEPT_ALLOWLIST entries actually exist as bot-tool exports", () => {
    const names = new Set(extractCreateToolNames());
    for (const tool of INTERCEPT_ALLOWLIST) {
      expect(names.has(tool), `INTERCEPT_ALLOWLIST entry '${tool}' is not in bot-tools.ts`).toBe(true);
    }
  });

  it("INTERCEPT_EXCLUDED entries actually exist as bot-tool exports", () => {
    const names = new Set(extractCreateToolNames());
    for (const tool of INTERCEPT_EXCLUDED) {
      expect(names.has(tool), `INTERCEPT_EXCLUDED entry '${tool}' is not in bot-tools.ts`).toBe(true);
    }
  });
});

